function stripFences(text: string) {
  return text.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '');
}

export async function POST(request: Request) {
  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'invalid JSON' }, { status: 400 });
  }

  const { text } = body;

  if (!text || typeof text !== 'string' || text.trim() === '') {
    return NextResponse.json({ error: 'text field is required' }, { status: 400 });
  }

  try {
    const message = await client.messages.create({
      model,
      max_tokens: 8192,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: (text as string).trim() }],
    });

    if (message.stop_reason === 'max_tokens') {
      return NextResponse.json({ error: 'contract too large to evaluate' }, { status: 422 });
    }

    const content = message.content[0];
    if (!content || content.type !== 'text') {
      return NextResponse.json({ error: 'unexpected response type' }, { status: 500 });
    }

    const raw = stripFences(content.text.trim());
    const parsed = JSON.parse(raw);
    const result = EvalResponseSchema.safeParse(parsed);

    if (!result.success) {
      return NextResponse.json({ error: 'model returned invalid response' }, { status: 500 });
    }

    return NextResponse.json(result.data);
  } catch (e) {
    const status = e instanceof Anthropic.APIError ? e.status : 500;
    return NextResponse.json({ error: 'evaluation failed' }, { status });
  }
}

